/**
 * Fixed-timestep game loop with render interpolation.
 *
 * - Update runs at a fixed `dt` via an accumulator.
 * - Frame times are clamped to 250ms to avoid the "spiral of death"
 *   (a huge frame must never trigger an unbounded number of catch-up ticks).
 * - After ticking, `alpha = accumulator / dt` (clamped to [0, 1]) is exposed
 *   for rendering: state = lerp(previousState, currentState, alpha).
 */

/** Maximum simulated time consumed by a single frame, in seconds. */
export const MAX_FRAME_TIME = 0.25;

export interface LoopState<T> {
  /** State produced by the most recent tick. */
  current: T;
  /** State produced by the tick before that (for interpolation). */
  previous: T;
}

export interface FixedLoop<T> {
  /** Feed one frame's wall-clock duration (seconds) and run fixed updates. */
  update(frameTime: number): void;
  /** Interpolation factor in [0, 1] for rendering between ticks. */
  alpha(): number;
  /** Number of fixed ticks executed so far. */
  tickCount(): number;
  /** Previous/current states around the current tick boundary. */
  state(): LoopState<T>;
}

export interface FixedLoopOptions<T> {
  /** Fixed timestep in seconds (e.g. 1/60). */
  dt: number;
  /**
   * Pure-ish step function advancing the simulation by exactly `dt`.
   * Must return the new state given the current state.
   */
  step: (state: T, dt: number) => T;
  /** Initial simulation state. Becomes both `previous` and `current`. */
  initial: T;
}

export function createFixedLoop<T>(options: FixedLoopOptions<T>): FixedLoop<T> {
  const { dt, step, initial } = options;
  if (!(dt > 0)) {
    throw new Error(`dt must be > 0, got ${dt}`);
  }

  let accumulator = 0;
  let ticks = 0;
  let previous: T = initial;
  let current: T = initial;

  return {
    update(frameTime: number): void {
      // Clamp pathological frames so a single stall can't cause an
      // unbounded number of catch-up ticks (spiral of death).
      accumulator += Math.min(frameTime, MAX_FRAME_TIME);

      while (accumulator >= dt) {
        previous = current;
        current = step(current, dt);
        accumulator -= dt;
        ticks++;
      }
    },

    alpha(): number {
      return Math.min(accumulator / dt, 1);
    },

    tickCount(): number {
      return ticks;
    },

    state(): LoopState<T> {
      return { previous, current };
    },
  };
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

