import { describe, expect, it } from "vitest";
import { createFixedLoop, lerp, MAX_FRAME_TIME } from "./loop.js";

interface Vec2 {
  x: number;
  y: number;
}

const DT = 1 / 60; // 60 Hz simulation
const VELOCITY: Vec2 = { x: 3, y: -1.5 }; // constant velocity, units/second

function makeDotLoop() {
  const step = (p: Vec2): Vec2 => ({
    x: p.x + VELOCITY.x * DT,
    y: p.y + VELOCITY.y * DT,
  });
  return createFixedLoop<Vec2>({ dt: DT, step, initial: { x: 0, y: 0 } });
}

/** Deterministic PRNG (mulberry32) so "mixed frames" are reproducible. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

describe("fixed-timestep loop", () => {
  it("interpolated position at alpha=0.5 is exactly midway between previous and current tick states", () => {
    const loop = makeDotLoop();

    // Advance exactly one tick's worth of time plus half a tick.
    // After update: accumulator = 1.5*dt -> one tick ran, alpha = 0.5.
    loop.update(DT + DT / 2);
    expect(loop.tickCount()).toBe(1);
    expect(loop.alpha()).toBeCloseTo(0.5, 12);

    const { previous, current } = loop.state();
    const mid = {
      x: (previous.x + current.x) / 2,
      y: (previous.y + current.y) / 2,
    };
    const rendered = {
      x: lerp(previous.x, current.x, loop.alpha()),
      y: lerp(previous.y, current.y, loop.alpha()),
    };

    expect(rendered.x).toBe(mid.x);
    expect(rendered.y).toBe(mid.y);
  });

  it("a pathological 10-second frame advances at most ceil(MAX_FRAME_TIME / dt) ticks", () => {
    const loop = makeDotLoop();
    loop.update(10); // one giant frame

    const maxTicks = Math.ceil(MAX_FRAME_TIME / DT); // ceil(0.25 / (1/60)) = 15
    expect(loop.tickCount()).toBe(maxTicks);

    // Leftover simulated time must be less than one tick.
    const leftover = loop.alpha() * DT;
    expect(leftover).toBeGreaterThanOrEqual(0);
    expect(leftover).toBeLessThan(DT);
  });

  it("total ticks after 1000 mixed frames is deterministic and repeatable", () => {
    const run = (): number => {
      const loop = makeDotLoop();
      const rand = mulberry32(1337);
      for (let i = 0; i < 1000; i++) {
        // Mixed frame times: mostly ~16.7ms with jitter, occasional stalls
        // and occasional near-zero frames — all under the clamp except stalls.
        const r = rand();
        let frameTime: number;
        if (r < 0.02) frameTime = 10; // pathological stall (clamped to 250ms)
        else if (r < 0.08) frameTime = rand() * 0.001; // tiny frame
        else frameTime = DT * (0.5 + rand()); // 8ms .. 25ms
        loop.update(frameTime);
      }
      return loop.tickCount();
    };

    const first = run();
    const second = run();
    expect(first).toBe(second);
    expect(second).toBe(run());

    // Sanity: clamped total simulated time = sum(min(frameTime, 0.25)).
    // Ticks must be within one of floor(simTime / dt).
    expect(first).toBeGreaterThan(900);
    expect(first).toBeLessThan(1100);
  });
});

